SQUARE_MIN_PX = 256               # short side must be at least this (skips icons)

DEFAULT_TIERS = "native,pdf,docx,ocr"   # add "media" (or use --tiers all) for audio/video

TEXT_EXT = {
    ".txt", ".md", ".markdown", ".csv", ".tsv", ".log", ".rtf",
    ".py", ".js", ".ts", ".css", ".ini", ".cfg", ".conf", ".yaml", ".yml", ".xml",
