# ============================================================
# TEXT EXTRACTION
# ============================================================

def decode_bytes(b: bytes) -> str:
    if b.startswith((b"\xff\xfe", b"\xfe\xff")):
        return b.decode("utf-16", errors="replace")
    if b.startswith(b"\xef\xbb\xbf"):
        return b[3:].decode("utf-8", errors="replace")
    try:
        return b.decode("utf-8")
    except UnicodeDecodeError:
        pass
    try:
        return b.decode("cp1252")
    except UnicodeDecodeError:
        return b.decode("latin-1")


_BLOCK_TAGS = {"p", "div", "br", "li", "tr", "h1", "h2", "h3", "h4", "h5", "h6", "section", "article"}


class _Strip(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.out, self.skip = [], 0

    def handle_starttag(self, tag, attrs):
        if tag in ("script", "style", "noscript"):
            self.skip += 1
        elif tag in _BLOCK_TAGS:
            self.out.append("\n")

    def handle_endtag(self, tag):
        if tag in ("script", "style", "noscript"):
            self.skip = max(0, self.skip - 1)

    def handle_data(self, d):
        if not self.skip:
            self.out.append(d)


def html_to_text(s: str) -> str:
    p = _Strip()
    p.feed(s)
    return re.sub(r"\n\s*\n\s*\n+", "\n\n", "".join(p.out)).strip()


def mhtml_text(path: Path) -> str:
    msg = email.message_from_bytes(path.read_bytes(), policy=email.policy.default)
    parts = []
    for part in msg.walk():
        ct = part.get_content_type()
        if ct not in ("text/html", "text/plain"):
            continue
        try:
            body = part.get_content()
        except Exception:
            raw = part.get_payload(decode=True) or b""
            body = decode_bytes(raw)
        parts.append(html_to_text(body) if ct == "text/html" else body)
    return "\n\n".join(x for x in parts if x.strip())


def pdf_text(path: Path, ocr_ok: bool) -> tuple[str, str]:
    from pypdf import PdfReader
    reader = PdfReader(str(path))
    if reader.is_encrypted:
        reader.decrypt("")
    doc = None
    ocr_pages, pieces = 0, []
    for i, page in enumerate(reader.pages, start=1):
        try:
            t = page.extract_text() or ""
        except Exception:
            t = ""
        if len(t.strip()) < 20 and ocr_ok and CAPS["fitz"] and CAPS["pytesseract"]:
            try:
                import fitz
                import pytesseract
                from PIL import Image
                if doc is None:
                    doc = fitz.open(str(path))
                pix = doc[i - 1].get_pixmap(dpi=200)
                img = Image.frombytes("RGB", (pix.width, pix.height), pix.samples)
                t2 = pytesseract.image_to_string(img)
                if t2.strip():
                    t, ocr_pages = t2, ocr_pages + 1
            except Exception:
                pass
        pieces.append(f"--- page {i} ---\n{t}")
    if doc is not None:
        doc.close()
    method = "pypdf" + (f"+ocr({ocr_pages}pg)" if ocr_pages else "")
    return "\n\n".join(pieces), method


def docx_text(path: Path) -> str:
    from docx import Document
    doc = Document(str(path))
    parts = [p.text for p in doc.paragraphs]
    for n, table in enumerate(doc.tables, start=1):
        parts.append(f"\n===== TABLE {n} =====")
        for row in table.rows:
            parts.append("\t".join(c.text for c in row.cells))
    return "\n".join(parts)


def image_ocr(path: Path) -> str | None:
    from PIL import Image, ImageOps
    import pytesseract
    with Image.open(path) as im:
        if im.width * im.height < 64 * 64:
            return None
        im = ImageOps.exif_transpose(im)
        if im.mode not in ("L", "RGB"):
            im = im.convert("RGB")
        return pytesseract.image_to_string(im)


_WHISPER = None


def transcribe(path: Path, model_name: str) -> str:
    global _WHISPER
    if _WHISPER is None:
        from faster_whisper import WhisperModel
        _WHISPER = WhisperModel(model_name, device="auto", compute_type="int8")
    segs, _info = _WHISPER.transcribe(str(path), vad_filter=True)

    def ts(x):
        x = int(x)
        return f"{x // 3600:02d}:{x % 3600 // 60:02d}:{x % 60:02d}"
    return "\n".join(f"[{ts(s.start)}] {s.text.strip()}" for s in segs)


def extract_text(path: Path, ext: str, tiers: set, args) -> tuple[str | None, str]:
    """Return (text, method) or (None, reason)."""
    if ext == ".pdf":
        if "pdf" not in tiers or not CAPS["pypdf"]:
            return None, "tier off / pypdf missing"
        return pdf_text(path, ocr_ok="ocr" in tiers)
    if ext == ".docx":
        if "docx" not in tiers or not CAPS["docx"]:
            return None, "tier off / python-docx missing"
        return docx_text(path), "python-docx"
    if ext in IMG_EXT:
        if "ocr" not in tiers or not (CAPS["pytesseract"] and CAPS["PIL"]):
            return None, "tier off / tesseract missing"
        t = image_ocr(path)
        return (t, "tesseract") if t is not None else (None, "too small for OCR")
    if ext in AUDIO_EXT or ext in VIDEO_EXT:
        if "media" not in tiers or not CAPS["faster_whisper"]:
            return None, "tier off / faster-whisper missing"
        return transcribe(path, args.whisper_model), f"whisper:{args.whisper_model}"
    if "native" not in tiers:
        return None, "tier off"
    if ext in (".mhtml", ".mht"):
        return mhtml_text(path), "mhtml"
    if ext in (".html", ".htm"):
        return html_to_text(decode_bytes(path.read_bytes())), "html-strip"
    if ext == ".json":
        raw = decode_bytes(path.read_bytes())
        try:
            return json.dumps(json.loads(raw), ensure_ascii=False, indent=2), "json"
        except Exception:
            return raw, "json-raw"
    if ext in TEXT_EXT:
        return decode_bytes(path.read_bytes()), "text"
    # sniff unknown extensions
    if path.stat().st_size <= 50_000_000:
        data = path.read_bytes()
        if b"\x00" not in data[:10000]:
            return decode_bytes(data), "sniffed-text"
    return None, "binary / no extractor"


# ============================================================
# TEXT PACKERS
# ============================================================

def _hdr(rel, sha, method, i, n):
    return f"\n===== SOURCE: {rel} | sha256:{sha[:16]} | {method} | part {i}/{n} =====\n"


def txt_blocks(rel, sha, method, b: bytes, limit: int):
    probe = len(_hdr(rel, sha, method, 9999, 9999).encode("utf-8"))
    room = max(limit - probe - 4, 1000)
    parts = split_bytes(b, room)
    for i, pb in enumerate(parts, start=1):
        yield _hdr(rel, sha, method, i, len(parts)).encode("utf-8") + pb + b"\n\n"


def json_records(rel, sha, kind, method, b: bytes, limit: int) -> list[str]:
    pieces = split_bytes(b, JSON_RECORD_TEXT)
    while True:
        n = len(pieces)
        recs = [json.dumps({"source": rel, "sha256": sha, "type": kind, "method": method,
                            "part": i + 1, "parts": n, "text": pb.decode("utf-8", errors="replace")},
                           ensure_ascii=False) for i, pb in enumerate(pieces)]
        if all(len(r.encode("utf-8")) < limit - 1000 for r in recs) or all(len(p) <= 1000 for p in pieces):
            return recs
        pieces = [x for pb in pieces for x in split_bytes(pb, max(1000, len(pb) // 2))]


class TxtPacker:
    def __init__(self, outdir: Path, stem: str, limit: int, hard: int, cb):
        self.outdir, self.stem, self.limit, self.hard, self.cb = outdir, stem, limit, hard, cb
        self.n = next_index(outdir, stem, ".txt")
        self.buf, self.size, self.rels, self.files = [], 0, set(), []

    def add(self, rel: str, block: bytes):
        if self.size + len(block) > self.limit:
            self.flush()
        self.buf.append(block)
        self.size += len(block)
        self.rels.add(rel)

    def flush(self):
        if not self.buf:
            return
        path = self.outdir / f"{self.stem}_{self.n:04d}.txt"
        self.n += 1
        path.write_bytes(b"".join(self.buf))
        self.files.append((path, self.hard))
        self.cb(path.name, self.rels)
        self.buf, self.size, self.rels = [], 0, set()


class JsonPacker:
    def __init__(self, outdir: Path, stem: str, limit: int, hard: int, cb):
        self.outdir, self.stem, self.limit, self.hard, self.cb = outdir, stem, limit, hard, cb
        self.n = next_index(outdir, stem, ".json")
        self.buf, self.size, self.rels, self.files = [], 5, set(), []   # 5 = "[\n" + "\n]\n"

    def add(self, rel: str, rec: str):
        b = rec.encode("utf-8")
        extra = len(b) + (2 if self.buf else 0)
        if self.buf and self.size + extra > self.limit:
            self.flush()
            extra = len(b)
        self.buf.append(b)
        self.size += extra
        self.rels.add(rel)

    def flush(self):
        if not self.buf:
            return
        path = self.outdir / f"{self.stem}_{self.n:04d}.json"
        self.n += 1
        path.write_bytes(b"[\n" + b",\n".join(self.buf) + b"\n]\n")
        self.files.append((path, self.hard))
        self.cb(path.name, self.rels)
        self.buf, self.size, self.rels = [], 5, set()


# ============================================================
# PDF PACKING
# ============================================================

def build_pdf(pages) -> bytes:
    from pypdf import PdfWriter
    w = PdfWriter()
    last = None
    for reader, idx, label in pages:
        w.add_page(reader.pages[idx])
        if label != last:
            try:
                w.add_outline_item(label[:120], len(w.pages) - 1)
            except Exception:
                pass
            last = label
    try:
        try:
            w.compress_identical_objects(remove_duplicates=True, remove_unreferenced=True)
        except TypeError:   # older pypdf
            w.compress_identical_objects(remove_identicals=True, remove_orphans=True)
    except Exception:
        pass
    buf = io.BytesIO()
    w.write(buf)
    return buf.getvalue()


class PdfPacker:
    """Greedy page-contiguous packing; real serialized size decides, estimates only save work."""

    def __init__(self, outdir: Path, stem: str, target: int, hard: int, cb):
        self.outdir, self.stem, self.target, self.hard, self.cb = outdir, stem, target, hard, cb
        self.n = next_index(outdir, stem, ".pdf")
        self.pages, self.est = [], 0
        self.files, self.skipped = [], []

    def add(self, reader, idx: int, est: int, label: str):
        while True:
            trial = self.pages + [(reader, idx, label)]
            est_total = self.est + est
            if est_total < self.target * 0.9:
                self.pages, self.est = trial, est_total
                return
            data = build_pdf(trial)
            if len(data) < self.target:
                self.pages, self.est = trial, len(data)
                return
            if not self.pages:                       # lone page at/over target
                self._write_pages(trial)
                return
            self.flush()

    def flush(self):
        if self.pages:
            self._write_pages(self.pages)
        self.pages, self.est = [], 0

    def _write_pages(self, pages):
        data = build_pdf(pages)
        if len(data) >= self.hard:
            if len(pages) > 1:
                mid = len(pages) // 2
                self._write_pages(pages[:mid])
                self._write_pages(pages[mid:])
            else:
                self.skipped.append(pages[0][2])
            return
        path = self.outdir / f"{self.stem}_{self.n:04d}.pdf"
        self.n += 1
        path.write_bytes(data)
        self.files.append((path, self.hard))
        self.cb(path.name, {p[2] for p in pages})


# ---------- to-PDF converters ----------

def _flatten_rgb(im):
    from PIL import Image, ImageOps
    im = ImageOps.exif_transpose(im)
    try:
        im.seek(0)
    except Exception:
        pass
    if im.mode in ("RGBA", "LA") or (im.mode == "P" and "transparency" in im.info):
        im = im.convert("RGBA")
        bg = Image.new("RGB", im.size, (255, 255, 255))
        bg.paste(im, mask=im.split()[-1])
        return bg
    return im.convert("RGB") if im.mode not in ("RGB", "L") else im


def _bytes_to_pdf(img_bytes: bytes, im) -> bytes:
    if CAPS["img2pdf"]:
        import img2pdf
        try:
            return img2pdf.convert(img_bytes)
        except Exception:
            pass
    buf = io.BytesIO()
    im.save(buf, "PDF", resolution=150)
    return buf.getvalue()


def image_lossless_pdf(path: Path) -> bytes | None:
    from PIL import Image
    if CAPS["img2pdf"]:
        import img2pdf
        try:
            return img2pdf.convert(str(path))
        except Exception:
            pass
    try:
        with Image.open(path) as im:
            im = _flatten_rgb(im)
            png = io.BytesIO()
            im.save(png, "PNG")
            return _bytes_to_pdf(png.getvalue(), im)
    except Exception:
        return None


def image_shrunk_pdf(path: Path, max_bytes: int) -> bytes | None:
    from PIL import Image
    try:
        with Image.open(path) as im0:
            im = _flatten_rgb(im0).convert("RGB")
    except Exception:
        return None
    for scale in (1.0, 0.85, 0.7, 0.55, 0.4, 0.3, 0.2):
        r = im if scale == 1.0 else im.resize(
            (max(1, int(im.width * scale)), max(1, int(im.height * scale))), Image.LANCZOS)
        for q in (85, 75, 65, 50, 40):
            jb = io.BytesIO()
            r.save(jb, "JPEG", quality=q, optimize=True)
            pdf = _bytes_to_pdf(jb.getvalue(), r)
            if len(pdf) < max_bytes:
                return pdf
    return None


def html_to_pdf(src: Path, out_pdf: Path, work: Path) -> bool:
    prof = Path(tempfile.mkdtemp(dir=work, prefix="browser_"))
    cmd = [CAPS["browser"], "--headless", "--disable-gpu", "--no-pdf-header-footer",
           "--allow-file-access-from-files", "--virtual-time-budget=10000",
           f"--user-data-dir={prof}", f"--print-to-pdf={out_pdf}", src.resolve().as_uri()]
    if os.name != "nt" and hasattr(os, "geteuid") and os.geteuid() == 0:
        cmd.insert(2, "--no-sandbox")
    try:
        subprocess.run(cmd, timeout=120, capture_output=True, stdin=subprocess.DEVNULL)
    except Exception:
        return False
    return out_pdf.exists() and out_pdf.stat().st_size > 0


def tex_to_pdf(src: Path, work: Path, sha: str) -> tuple[Path | None, str]:
    text = decode_bytes(src.read_bytes())
    if r"\documentclass" not in text:
        return None, "FRAGMENT (no \\documentclass); text only"
    engines = [e for e in ("lualatex", "pdflatex") if CAPS[e]]
    if not engines:
        return None, "NO_LATEX_INSTALLED"
    head = text[:600].lower()
    if "lualatex" in head or "fontspec" in text or "\\directlua" in text or "luacode" in text:
        engines.sort(key=lambda e: e != "lualatex")
    else:
        engines.sort(key=lambda e: e != "pdflatex")
    tmp = work / f"tex_{sha[:12]}"
    tmp.mkdir(exist_ok=True)
    for sib in src.parent.iterdir():
        try:
            if sib.is_file() and sib.suffix.lower() in TEX_SIBLING_EXT and sib.stat().st_size < 50_000_000:
                shutil.copy2(sib, tmp / sib.name)
            elif sib.is_dir() and sib.name.lower() in TEX_FIG_DIRS:
                shutil.copytree(sib, tmp / sib.name, dirs_exist_ok=True)
        except Exception:
            pass
    stem = src.stem
    use_bib = bool(re.search(r"\\bibliography\{", text)) and CAPS["bibtex"]
    for eng in engines:
        cmd = [CAPS[eng], "-interaction=nonstopmode", f"{src.name}"]
        try:
            for step in range(3):
                if step == 1 and use_bib:
                    subprocess.run([CAPS["bibtex"], stem], cwd=tmp, timeout=120,
                                   capture_output=True, stdin=subprocess.DEVNULL)
                r = subprocess.run(cmd, cwd=tmp, timeout=240, capture_output=True,
                                   stdin=subprocess.DEVNULL)
            pdf = tmp / f"{stem}.pdf"
            if pdf.exists() and pdf.stat().st_size > 0:
                return pdf, f"COMPILED ({eng}{'' if r.returncode == 0 else ', with errors'})"
        except Exception:
            continue
    return None, "COMPILE_FAILED (see source text packet)"


def office_to_pdf(src: Path, work: Path, sha: str) -> Path | None:
    out = work / f"office_{sha[:12]}"
    out.mkdir(exist_ok=True)
    try:
        subprocess.run([CAPS["soffice"], "--headless", "--convert-to", "pdf", "--outdir", str(out),
                        str(src)], timeout=240, capture_output=True, stdin=subprocess.DEVNULL)
    except Exception:
        return None
    pdf = out / f"{src.stem}.pdf"
    return pdf if pdf.exists() else None


def visual_kind(ext: str) -> str | None:
    if ext in IMG_EXT:
        return "image"
    if ext == ".pdf":
        return "pdf"
    if ext in HTML_EXT:
        return "html"
    if ext == ".tex":
        return "tex"
    if ext in OFFICE_EXT:
        return "office"
    return None


# ============================================================
# SQUARE IMAGES
# ============================================================

def save_square(path: Path, sha: str, outdir: Path, tol: float, min_px: int) -> tuple[str, str]:
    from PIL import Image, ImageOps
    with Image.open(path) as im:
        w, h = im.size
        if min(w, h) < min_px:
            return "not_square", f"{w}x{h} below {min_px}px"
        if abs(w / h - 1.0) > tol:
            return "not_square", f"{w}x{h}"
    ext = path.suffix.lower()
    stem = re.sub(r'[<>:"/\\|?*]', "_", path.stem)[:80]
    if ext in (".png", ".jpg", ".jpeg") and path.stat().st_size < GIT_HARD:
        dest = outdir / f"{stem}__{sha[:8]}{ext}"
        shutil.copy2(path, dest)
        return "saved", dest.name
    with Image.open(path) as im0:
        im = ImageOps.exif_transpose(im0)
        has_alpha = im.mode in ("RGBA", "LA") or (im.mode == "P" and "transparency" in im.info)
        im = im.convert("RGBA" if has_alpha else "RGB")
        out_ext = ".png" if has_alpha else ".jpg"
        dest = outdir / f"{stem}__{sha[:8]}{out_ext}"
        scale = 1.0
        while True:
            r = im if scale == 1.0 else im.resize((int(im.width * scale), int(im.height * scale)),
                                                  Image.LANCZOS)
            if has_alpha:
                r.save(dest, "PNG", optimize=True)
            else:
                r.save(dest, "JPEG", quality=95, optimize=True)
            if dest.stat().st_size < GIT_HARD:
                return "saved_converted", dest.name
            scale *= 0.85


# ============================================================
# INVENTORY / DEDUPE / ARCHIVE
# ============================================================

def dedupe_key(p: Path):
    # prefer the "original" over " (1)" / "__collision_" copies, then shorter path
    copyish = bool(re.search(r" \(\d+\)$|__collision_\d+$", p.stem))
    return (copyish, len(str(p)), str(p))


def inventory(src: Path, recurse: bool, excludes: list[Path]) -> list[Path]:
    it = src.rglob("*") if recurse else src.glob("*")
    out = []
    for p in it:
        if not p.is_file():
            continue
        n = norm(p)
        if any(e in n.parents for e in excludes):
            continue
        out.append(p)
    return sorted(out, key=dedupe_key)


def archive_files(src: Path, keep: list[tuple[Path, str]], dest: Path, recurse: bool,
                  verify: str) -> list[str]:
    problems = []
    for p, h in keep:
        rel = p.relative_to(src)
        d = dest / rel
        d.parent.mkdir(parents=True, exist_ok=True)
        try:
            shutil.copy2(p, d)
            ok = d.stat().st_size == p.stat().st_size
            if ok and verify == "hash":
                ok = sha256(d) == h
            if not ok:
                problems.append(f"verify failed, original kept: {rel}")
                continue
            force_unlink(p)
        except Exception as exc:
            problems.append(f"{rel}: {exc}")
    if recurse:
        dirs = sorted((d for d in src.rglob("*") if d.is_dir()),
                      key=lambda d: len(d.parts), reverse=True)
        for d in dirs:
            try:
                d.rmdir()
            except OSError:
                pass
    return problems


# ============================================================
# MAIN
# ============================================================

def main():
    ap = argparse.ArgumentParser(description="Dedupe, extract, pack, archive.")
    ap.add_argument("--source", help="folder to process (default: DEFAULT_SOURCE; asked if omitted)")
    g = ap.add_mutually_exclusive_group()
    g.add_argument("--recurse", dest="recurse", action="store_true", default=None)
    g.add_argument("--no-recurse", dest="recurse", action="store_false")
    ap.add_argument("--notefeed", default=NOTEFEED)
    ap.add_argument("--gitomatic", default=GITOMATIC)
    ap.add_argument("--archive-root", default=ARCHIVE_ROOT)
    ap.add_argument("--tag", help="label used in output file names (default: initials of folder name)")
    ap.add_argument("--tiers", default=DEFAULT_TIERS,
                    help="comma list of native,pdf,docx,ocr,media or 'all'")
    ap.add_argument("--whisper-model", default="small")
    ap.add_argument("--square-tol", type=float, default=SQUARE_TOL)
    ap.add_argument("--square-min", type=int, default=SQUARE_MIN_PX)
    ap.add_argument("--archive-verify", choices=["hash", "size"], default="hash")
    ap.add_argument("--keep-dups", action="store_true", help="do not delete exact duplicates")
    ap.add_argument("--no-archive", action="store_true", help="skip the archive-and-empty step")
    ap.add_argument("--dry-run", action="store_true", help="inventory + dedupe report only")
    ap.add_argument("--yes", action="store_true", help="skip the confirmation prompt")
    args = ap.parse_args()

    tiers = {"native", "pdf", "docx", "ocr", "media"} if args.tiers == "all" else \
        {t.strip() for t in args.tiers.split(",") if t.strip()}

    # ---- which folder, recurse or not
    src_str = args.source or ask_text("Folder to process?", DEFAULT_SOURCE)
    src = Path(src_str).expanduser()
    if not src.is_dir():
        die(f"Source folder does not exist: {src}")
    src = src.resolve()
    recurse = args.recurse
    if recurse is None:
        recurse = ask_yn("Recurse into subfolders?", True)

    note_dir, git_dir = Path(args.notefeed), Path(args.gitomatic)
    arch_root = Path(args.archive_root)

    # ---- safety: source must not overlap outputs/archive; no drive roots
    if len(src.parts) < 3:
        die(f"Refusing to treat {src} as a source (too close to a drive root).")
    for label, o in (("NoteFeed", note_dir), ("Git-O-Matic", git_dir), ("archive root", arch_root)):
        a, b = norm(src), norm(o) if o.exists() else Path(os.path.normcase(str(o.absolute())))
        if a == b or a in b.parents or b in a.parents:
            die(f"Source and {label} overlap: {src} <-> {o}")

    detect_caps()
    print(f"\nSource:    {src}   ({'recursive' if recurse else 'top level only'})")
    print(f"NoteFeed:  {note_dir}\nGit-O-Matic: {git_dir}\nArchive:   {arch_root}\n")
    print_caps(tiers)

    # ---- inventory + dedupe (hashing only; nothing touched yet)
    print("\nHashing...")
    files = inventory(src, recurse, [])
    if not files:
        die("No files found.")
    seen, keep, dups = {}, [], []
    for i, p in enumerate(files, 1):
        h = sha256(p)
        if h in seen:
            dups.append((p, h, seen[h]))
        else:
            seen[h] = p
            keep.append((p, h))
        if i % 200 == 0:
            print(f"  hashed {i}/{len(files)}")
    keep.sort(key=lambda t: str(t[0]).lower())      # packets follow natural path order
    dup_bytes = sum(p.stat().st_size for p, _, _ in dups)
    kinds = {}
    for p, _ in keep:
        e = p.suffix.lower() or "(none)"
        kinds[e] = kinds.get(e, 0) + 1
    print(f"\n{len(files)} files found: {len(keep)} unique, {len(dups)} exact duplicates "
          f"({dup_bytes / 1e6:.1f} MB)")
    print("By extension (unique): " + ", ".join(f"{k}:{v}" for k, v in sorted(kinds.items())))

    if args.dry_run:
        for p, _, o in dups:
            print(f"  DUP  {p.relative_to(src)}   == {o.relative_to(src)}")
        print("\nDry run: nothing written.")
        return

    will_archive = not args.no_archive
    stamp = dt.datetime.now().strftime("%Y-%m-%d_%H%M%S")
    arch_dest = arch_root / f"{stamp}_{src.name}"
    print("\nPlan:")
    print(f"  - write packets to NoteFeed and Git-O-Matic")
    if will_archive:
        print(f"  - after outputs verify: {'delete ' + str(len(dups)) + ' exact duplicates, then ' if dups and not args.keep_dups else ''}"
              f"move all {len(keep)} unique files to {arch_dest}")
        print(f"  - source folder {src} is left empty")
    else:
        print("  - no archive step (--no-archive); source untouched")
    if not args.yes and not ask_yn("Proceed?", False):
        print("Aborted; nothing changed.")
        return

    # ---- set up outputs
    note_dir.mkdir(parents=True, exist_ok=True)
    git_dir.mkdir(parents=True, exist_ok=True)
    date = dt.date.today().isoformat()
    tag = args.tag or abbreviate(src.name)
    work = Path(tempfile.mkdtemp(prefix="iceberg_work_"))
    (work / "text").mkdir()

    M: dict = {}

    def cb(name, rels):
        for r in rels:
            M.setdefault(r, {}).setdefault("packets", []).append(name)

    note_txt = TxtPacker(note_dir, f"{date}_{tag}_txt", NOTE_TARGET, NOTE_HARD, cb)
    git_json = JsonPacker(git_dir, f"{date}_{tag}_json", GIT_TARGET, GIT_HARD, cb)
    note_pdf = PdfPacker(note_dir, f"{date}_{tag}_pdf", NOTE_TARGET, NOTE_HARD, cb) if CAPS["pypdf"] else None
    git_pdf = PdfPacker(git_dir, f"{date}_{tag}_pdf", GIT_TARGET, GIT_HARD, cb) if CAPS["pypdf"] else None
    square_files = []

    # ---- main pass
    total = len(keep)
    for n, (p, h) in enumerate(keep, 1):
        rel = p.relative_to(src).as_posix()
        ext = p.suffix.lower()
        m = M.setdefault(rel, {})
        m.update({"sha256": h, "bytes": p.stat().st_size, "ext": ext})
        print(f"[{n}/{total}] {rel}")

        # TEXT
        try:
            text, method = extract_text(p, ext, tiers, args)
            if text is not None and text.strip():
                b = text.encode("utf-8", errors="replace")
                for blk in txt_blocks(rel, h, method, b, NOTE_TARGET):
                    note_txt.add(rel, blk)
                for rec in json_records(rel, h, ext or "none", method, b, GIT_TARGET):
                    git_json.add(rel, rec)
                m["text"] = {"status": "extracted", "method": method, "chars": len(text)}
            else:
                m["text"] = {"status": "none", "reason": method if text is None else "empty"}
        except Exception as exc:
            m["text"] = {"status": "error", "reason": str(exc)[:200]}
            print(f"    text error: {exc}")

        # VISUAL -> PDF packets
        vk = visual_kind(ext)
        if vk and note_pdf:
            try:
                if vk == "image" and CAPS["PIL"]:
                    lossless = image_lossless_pdf(p)
                    gl, nl = GIT_TARGET - 100_000, NOTE_TARGET - 100_000
                    gb = lossless if lossless and len(lossless) < gl else image_shrunk_pdf(p, gl)
                    nb = lossless if lossless and len(lossless) < nl else image_shrunk_pdf(p, nl)
                    from pypdf import PdfReader
                    res = []
                    for packer, data, nm in ((git_pdf, gb, "git"), (note_pdf, nb, "note")):
                        if data is None:
                            res.append(f"{nm}:FAILED")
                        else:
                            packer.add(PdfReader(io.BytesIO(data)), 0, len(data), rel)
                            res.append(f"{nm}:{'lossless' if data is lossless else 'recompressed'}")
                    m["pdf"] = {"status": "packed", "detail": ", ".join(res)}
                else:
                    pdf_path, detail = None, ""
                    if vk == "pdf":
                        pdf_path, detail = p, "source pdf"
                    elif vk == "html":
                        if CAPS["browser"]:
                            outp = work / f"html_{h[:12]}.pdf"
                            pdf_path = outp if html_to_pdf(p, outp, work) else None
                            detail = "rendered via browser" if pdf_path else "BROWSER_RENDER_FAILED"
                        else:
                            detail = "NO_BROWSER"
                    elif vk == "tex":
                        pdf_path, detail = tex_to_pdf(p, work, h)
                    elif vk == "office":
                        if CAPS["soffice"]:
                            pdf_path = office_to_pdf(p, work, h)
                            detail = "converted via LibreOffice" if pdf_path else "OFFICE_CONVERT_FAILED"
                        else:
                            detail = "NO_LIBREOFFICE"
                    if pdf_path is not None:
                        from pypdf import PdfReader
                        reader = PdfReader(str(pdf_path))
                        if reader.is_encrypted:
                            reader.decrypt("")
                        pages = len(reader.pages)
                        est = max(1, pdf_path.stat().st_size // max(1, pages))
                        for i in range(pages):
                            git_pdf.add(reader, i, est, rel)
                            note_pdf.add(reader, i, est, rel)
                        m["pdf"] = {"status": "packed", "detail": detail, "pages": pages}
                    else:
                        m["pdf"] = {"status": "skipped", "detail": detail}
            except Exception as exc:
                m["pdf"] = {"status": "error", "detail": str(exc)[:200]}
                print(f"    pdf error: {exc}")

        # SQUARE images
        if ext in IMG_EXT and CAPS["PIL"]:
            try:
                st, detail = save_square(p, h, git_dir, args.square_tol, args.square_min)
                m["square"] = {"status": st, "detail": detail}
                if st.startswith("saved"):
                    square_files.append((git_dir / detail, GIT_HARD))
            except Exception as exc:
                m["square"] = {"status": "error", "detail": str(exc)[:200]}

    # ---- flush
    for packer in (note_txt, git_json, note_pdf, git_pdf):
        if packer:
            packer.flush()

    for packer, name in ((note_pdf, "NoteFeed pdf"), (git_pdf, "Git-O-Matic pdf")):
        if packer and packer.skipped:
            print(f"\nWARNING: {name}: {len(set(packer.skipped))} source(s) had a single page "
                  f"over the hard cap and were left out of those packets "
                  f"(still archived, listed in manifest): {sorted(set(packer.skipped))[:10]}")
            for lab in set(packer.skipped):
                M.setdefault(lab, {}).setdefault("pdf", {}).setdefault("oversize_page_skipped_in", []).append(name)

    # ---- verify outputs
    print("\nVerifying outputs...")
    problems = []
    outputs = (note_txt.files + git_json.files + square_files
               + (note_pdf.files if note_pdf else []) + (git_pdf.files if git_pdf else []))
    for path, hard in outputs:
        try:
            size = path.stat().st_size
        except FileNotFoundError:
            problems.append(f"missing output: {path}")
            continue
        if size >= hard:
            problems.append(f"{path.name} is {size} bytes, not under {hard}")
        if path.suffix == ".json":
            try:
                json.loads(path.read_text(encoding="utf-8"))
            except Exception as exc:
                problems.append(f"{path.name} is not valid JSON: {exc}")
        if path.suffix == ".pdf":
            try:
                from pypdf import PdfReader
                if len(PdfReader(str(path)).pages) == 0:
                    problems.append(f"{path.name} has no pages")
            except Exception as exc:
                problems.append(f"{path.name} unreadable as PDF: {exc}")

    counts = {
        "txt packets": len(note_txt.files), "json packets": len(git_json.files),
        "NoteFeed pdf packets": len(note_pdf.files) if note_pdf else 0,
        "Git-O-Matic pdf packets": len(git_pdf.files) if git_pdf else 0,
        "square images": len(square_files),
    }
    print("Outputs: " + ", ".join(f"{k}={v}" for k, v in counts.items()))

    # ---- manifest
    manifest = {
        "run": stamp, "source": str(src), "recursive": recurse, "tag": tag,
        "counts": counts, "output_problems": problems,
        "duplicates_deleted": [{"path": p.relative_to(src).as_posix(), "sha256": h,
                                "kept": o.relative_to(src).as_posix()} for p, h, o in dups],
        "files": M,
    }
    runs = Path.cwd() / "_iceberg_runs"
    runs.mkdir(exist_ok=True)
    mpath = runs / f"{stamp}_{tag}_manifest.json"
    mpath.write_text(json.dumps(manifest, indent=2, ensure_ascii=False), encoding="utf-8")
    print(f"Manifest: {mpath}")

    shutil.rmtree(work, ignore_errors=True)

    # ---- finalize (destructive part)
    if not will_archive:
        print("\nDone (no archive step).")
        return
    if problems:
        print("\nOutput verification FAILED; NOT deleting duplicates, NOT archiving. Source is untouched.")
        for pr in problems:
            print("  -", pr)
        raise SystemExit(1)

    if dups and not args.keep_dups:
        n_del = 0
        for p, h, o in dups:
            if o.exists():
                force_unlink(p)
                n_del += 1
        print(f"\nDeleted {n_del} exact duplicates.")

    print(f"Archiving {len(keep)} files to {arch_dest} ...")
    arch_dest.mkdir(parents=True, exist_ok=True)
    problems = archive_files(src, keep, arch_dest, recurse, args.archive_verify)
    shutil.copy2(mpath, arch_dest / mpath.name)
    left = list(src.iterdir())
    if problems:
        print("\nArchive problems (affected originals were kept):")
        for pr in problems:
            print("  -", pr)
        raise SystemExit(1)
    if left:
        print(f"\nArchived. {len(left)} item(s) remain in source "
              f"({'subfolders, since recursion was off' if not recurse else 'unexpected'}): "
              + ", ".join(x.name for x in left[:8]))
    else:
        print(f"\nArchived. {src} is now empty.")


if __name__ == "__main__":
    main()

