        p.unlink()
    except PermissionError:
        os.chmod(p, stat.S_IWRITE)
        p.unlink()


def ask_text(prompt: str, default: str) -> str:
    try:
        a = input(f"{prompt}\n  [Enter = {default}]: ").strip().strip('"').strip("'")
    except EOFError:
        die("Input needed but stdin is not interactive; pass the matching command-line flag.")
    return a or default


def ask_yn(prompt: str, default: bool) -> bool:
    suffix = " [Y/n]: " if default else " [y/N]: "
    while True:
        try:
            a = input(prompt + suffix).strip().lower()
        except EOFError:
            die("Input needed but stdin is not interactive; pass the matching command-line flag.")
        if not a:
            return default
        if a in ("y", "yes"):
            return True
        if a in ("n", "no"):
            return False


def norm(p: Path) -> Path:
    return Path(os.path.normcase(str(p.resolve())))


def next_index(outdir: Path, stem: str, ext: str) -> int:
    pat = re.compile(re.escape(stem) + r"_(\d{4})" + re.escape(ext) + r"$")
    nums = []
    for f in outdir.glob(f"{stem}_*{ext}"):
        m = pat.match(f.name)
        if m:
            nums.append(int(m.group(1)))
    return max(nums, default=0) + 1


def split_bytes(b: bytes, limit: int) -> list[bytes]:
    """Split bytes into pieces <= limit, preferring newline breaks, never cutting a UTF-8 char."""
    out, i, n = [], 0, len(b)
    limit = max(limit, 16)
    while i < n:
        j = min(i + limit, n)
        if j < n:
            k = b.rfind(b"\n", i + int(limit * 0.75), j)
            if k != -1:
                j = k + 1
            else:
                while j > i + 1 and (b[j] & 0xC0) == 0x80:
                    j -= 1
        out.append(b[i:j])
        i = j
    return out


def abbreviate(name: str) -> str:
    words = [w for w in re.split(r"[^A-Za-z0-9]+", name) if w]
    if len(words) >= 2:
        return "".join(w[0].upper() for w in words)[:12]
    return (words[0] if words else "SRC")[:12].upper()


